// Port of app/sidekiq/generate_community_chat_recap_job.rb up to the generator. `CommunityChatRecap.find` runs in Node; the recap is
// generated by CommunityChatRecapGeneratorService (a model API call), so a recap that exists hands back before it.
// Its sidekiq_retries_exhausted (FailureHandler) runs here: the recap is marked failed with the error message and its run is let to
// finish (CommunityChatRecapRun#check_if_finished!, which also queues the weekly run and the notifications).
// Golden: __fixtures__/generate-community-chat-recap-job.golden.json (scripts/golden/generate-community-chat-recap-job.rb).
import type { CommunityChatRecap } from "@prisma/client";

import { HandBackToRuby, beforeSideEffects } from "../../server/jobs/hand-back.ts";
import {
  checkRunOfRecapFinishedBang,
  CommunityChatRecaps,
  RECAP_STATUSES,
} from "../../server/models/community-chat-recap-run.ts";
import { withJobsRuntime } from "../../server/models/concerns/job-runtime.ts";
import { findByIdBang, findOneBy, recordIdFrom } from "../../server/models/row-reads.ts";
import { castRow } from "../../server/models/sql.ts";
import type { RetriesExhausted } from "../retry.ts";

import { findNothing, lookupKey } from "./payout-note-retries-exhausted-jobs.ts";
import { modelJob } from "./support/job-deps.ts";

const JOB_CLASS = "GenerateCommunityChatRecapJob";

export const generateCommunityChatRecapJobWith = modelJob({ min: 1 }, async ([recapId]) => {
  const id = await beforeSideEffects(() => recordIdFrom(recapId, "CommunityChatRecap.find"));
  await findByIdBang("CommunityChatRecap", id);

  throw new HandBackToRuby("the recap is generated by the model");
});
export const generateCommunityChatRecapJob = generateCommunityChatRecapJobWith();

// `recap_id.blank?` for what JSON can carry.
const isBlank = (value: unknown) =>
  value === null ||
  value === undefined ||
  value === false ||
  (typeof value === "string" && !/\S/u.test(value)) ||
  (Array.isArray(value) && value.length === 0);

export const generateCommunityChatRecapJobRetriesExhaustedWith =
  (overrides: { now?: () => Date } = {}): RetriesExhausted =>
  (msg, error, { runtime }) => {
    const now = overrides.now ?? (() => new Date());
    return withJobsRuntime(runtime, async () => {
      if (msg.class !== JOB_CLASS) return;
      const recapId = Array.isArray(msg.args) ? msg.args[0] : undefined;
      if (isBlank(recapId)) return;

      const key = lookupKey(recapId);
      const row =
        key === "nothing"
          ? await findNothing("community_chat_recaps")
          : await findOneBy<CommunityChatRecap>("CommunityChatRecap", "id", key, true);
      if (!row) return;

      const recap = CommunityChatRecaps.load(castRow<CommunityChatRecap>("CommunityChatRecap", row));
      const message = error instanceof Error ? error.message : String(error);
      await CommunityChatRecaps.updateBang(recap, { status: RECAP_STATUSES.failed, error_message: message }, { now });
      await checkRunOfRecapFinishedBang(recap, now);
    });
  };
export const generateCommunityChatRecapJobRetriesExhausted = generateCommunityChatRecapJobRetriesExhaustedWith();
